    location, description, culture, benefits, tech_stack,
    contact_email, contact_phone, website_url, status, created_at, updated_at
) VALUES (
    157, gen_random_uuid(), '(주)보나비젼', 'https://cdn.fitme.co.kr/employers/157/logo.png', 'Enterprise Software', 2017, 10,
    '대구광역시 수성구', '(주)보나비젼 - Enterprise Software', '[성장] 성장 지향적 문화로, 지속적인 학습과 개선을 장려합니다. [기술] 코드리뷰·기술 공유 세션·사내 스터디가 일상화되어 있으며, 외부 컨퍼런스 발표·블로그 작성 등을 지원합니다. [평가] 결과보다 과정과 학습을 함께 평가하고, 1:1 멘토링으로 성장을 돕습니다.', '[보상] 스톡옵션 부여 및 성과에 따른 스톡그랜트, 연봉 상위 10% 수준 유지, 분기별 성과급(최대 200%) 지급. [근무] 유연근무제(코어타임 11~15시), 재택·원격 근무 주 2일, 연차 외 리프레시 휴가 5일. [지원] 최신 개발 장비 지급(MacBook Pro 등), 도서·강의·자격증 비용 전액 지원, 사내 카페 무료 이용, 점심 식대 지원.', 'Redis, MySQL, OpenAI, AWS, TypeScript, Docker, Python, React',
    'hr@.com', '01086347542', 'https://.kr', 'ACTIVE', now(), now()
)
ON CONFLICT (employer_id) DO UPDATE SET 
    name = EXCLUDED.name, logo_url = EXCLUDED.logo_url, industry = EXCLUDED.industry, 
