    location, description, culture, benefits, tech_stack,
    contact_email, contact_phone, website_url, status, created_at, updated_at
) VALUES (
    400, gen_random_uuid(), '수퍼게이트 주식회사', 'https://cdn.fitme.co.kr/employers/400/logo.png', 'Mobile Platform', 2001, 30,
    '인천광역시 연수구', '수퍼게이트 주식회사 - Mobile Platform', '[글로벌] 글로벌 지향으로 다국적 팀 구성, 영어 회의·문서 사용이 일상입니다. [성장] 해외 오피스 출장·파견, 해외 컨퍼런스 참가, 해외 인재 영입을 지원합니다. [다양성] 다양한 배경과 관점을 존중하고, 원격 협업 도구를 적극 활용합니다.', '[보상] 연봉 상위 10% 목표, 연 2회 인사평가 및 조정, 성과급 200% 목표. [근무] 자율 출퇴근, 무제한 휴가(최소 사용 권장), 주 4.5일제 선택 가능. [지원] 도서구입비 무제한, 컨퍼런스·밋업 참가비·숙박 지원, 자기계발비 연 300만원, 사내 헬스장·요가실 이용. [기타] 명절 보너스, 경조사 지원, 스탁옵션.', 'Redis, OpenAI, GitHub Actions, AWS, React, Django, HuggingFace',
    'hr@.com', '01071992786', 'https://.co.kr', 'ACTIVE', now(), now()
)
ON CONFLICT (employer_id) DO UPDATE SET 
    name = EXCLUDED.name, logo_url = EXCLUDED.logo_url, industry = EXCLUDED.industry, 
    founded_year = EXCLUDED.founded_year, employee_count = EXCLUDED.employee_count,
    location = EXCLUDED.location, description = EXCLUDED.description, culture = EXCLUDED.culture,
    benefits = EXCLUDED.benefits, tech_stack = EXCLUDED.tech_stack,
    contact_email = EXCLUDED.contact_email, contact_phone = EXCLUDED.contact_phone, website_url = EXCLUDED.website_url,
    status = EXCLUDED.status, updated_at = now();
